//! This sidecar is captured by the independent original-Python oracle. Expected
//! values are never generated by this Rust crate or its two provider consumers.

use ordered_python_compat::{
    CoercionError, PyValue, loads, pyfloat, pyint, pyrepr, pystr, pystrip, pytruthy,
};
use serde_json::Value;

fn exception(error: CoercionError) -> &'static str {
    match error {
        CoercionError::Type => "TypeError",
        CoercionError::Value => "ValueError",
        CoercionError::Overflow => "OverflowError",
    }
}

fn hex_bits(value: &str) -> u64 {
    let (sign, unsigned) = value
        .strip_prefix('-')
        .map_or((0, value), |value| (1u64 << 63, value));
    let (mantissa, exponent) = unsigned
        .strip_prefix("0x")
        .unwrap()
        .split_once('p')
        .unwrap();
    let (whole, fraction) = mantissa.split_once('.').unwrap();
    let fraction = u64::from_str_radix(fraction, 16).unwrap();
    if whole == "0" {
        sign | fraction
    } else {
        let exponent: i32 = exponent.parse().unwrap();
        sign | ((exponent + 1023) as u64) << 52 | fraction
    }
}

fn check_float(input: &PyValue, expected: &Value, id: &str) {
    match pyfloat(input) {
        Err(error) => {
            assert_eq!(expected["kind"], "error", "{id}: float");
            assert_eq!(expected["exception_class"], exception(error), "{id}: float");
        }
        Ok(value) => {
            assert_eq!(expected["kind"], "result", "{id}: float");
            let hex = expected["hex"].as_str().unwrap();
            match hex {
                "nan" => assert!(value.is_nan(), "{id}: float"),
                "inf" => assert_eq!(value, f64::INFINITY, "{id}: float"),
                "-inf" => assert_eq!(value, f64::NEG_INFINITY, "{id}: float"),
                _ => assert_eq!(value.to_bits(), hex_bits(hex), "{id}: float"),
            }
            assert_eq!(
                pystr(&PyValue::Float(value)),
                expected["str"].as_str().unwrap(),
                "{id}: float str"
            );
        }
    }
}

#[test]
fn original_cpython_scalar_observations_match_without_expected_rewriting() {
    let scalar_raw = include_str!("scalar-vectors.json");
    assert_eq!(
        tobkiri_canon::hash_bytes(scalar_raw.as_bytes()).hex(),
        "30dc0130c89da4e724191f364f7c39f529f2a2a85a618a1c8500a309be7ce6c8"
    );
    let artifact: Value = serde_json::from_str(scalar_raw).unwrap();
    assert_eq!(artifact["schema"], "io.tobkiri.python-scalar-compat.v1");
    assert_eq!(
        artifact["value_codec"]["sha256"],
        "495b613a37807cf10e831a2332b7f401148d3aaec29ec84c16a22f0a2c05d3a2"
    );
    let unicode_raw = include_str!("../src/unicode15_1.json");
    assert_eq!(
        tobkiri_canon::hash_bytes(unicode_raw.as_bytes()).hex(),
        "de90b159e3f054914ed532d02df8964988741fd2787c01959c9b1e4c2820fa55"
    );
    let unicode: Value = serde_json::from_str(unicode_raw).unwrap();
    assert_eq!(unicode["unicode_version"], "15.1.0");
    assert_eq!(unicode["runtime"], artifact["runtime"]);
    assert_eq!(
        unicode["source_manifest_sha256"],
        artifact["source_manifest_sha256"]
    );
    let vectors = artifact["vectors"].as_array().unwrap();
    assert!(!vectors.is_empty());
    for vector in vectors {
        let id = vector["id"].as_str().unwrap();
        let raw = vector["input_json"].as_str().unwrap();
        assert_eq!(
            tobkiri_canon::hash_bytes(raw.as_bytes()).hex(),
            vector["input_utf8"]["sha256"].as_str().unwrap(),
            "{id}: input identity"
        );
        let value = loads(raw).unwrap();
        let observations = &vector["observations"];
        check_float(&value, &observations["float"], id);
        match pyint(&value) {
            Err(error) => {
                assert_eq!(observations["int"]["kind"], "error", "{id}: int");
                assert_eq!(
                    observations["int"]["exception_class"],
                    exception(error),
                    "{id}: int"
                );
            }
            Ok(value) => {
                assert_eq!(observations["int"]["kind"], "result", "{id}: int");
                assert_eq!(
                    value,
                    observations["int"]["decimal"].as_str().unwrap(),
                    "{id}: int"
                );
            }
        }
        assert_eq!(
            pystr(&value),
            observations["str"]["value"].as_str().unwrap(),
            "{id}: str"
        );
        assert_eq!(
            pyrepr(&value),
            observations["repr"]["value"].as_str().unwrap(),
            "{id}: repr"
        );
        assert_eq!(
            pytruthy(&value),
            observations["truthy"]["value"].as_bool().unwrap(),
            "{id}: truthy"
        );
        assert_eq!(
            pystrip(&pystr(&value)),
            observations["strip"]["value"].as_str().unwrap(),
            "{id}: strip"
        );
    }
}
